window.bookSummaryJSON = "<p><i>New York Times</i> best-selling author Cinda Williams Chima has been crafting riveting novels since her days in middle school. In <i>The Exiled Queen</i>, 17-year-old ex-Ragmarket street lord Han Alister is pursuing an education in magical arts. To stand up to the haters at the academy, he joins forces with a mysterious wizard—but soon discovers the price may be more than he's willing to pay.</p>"; 
